/**
 * Inauspicious periods of the day (Rahu Kalam, Yamagandam, Gulika Kalam).
 *
 * Traditional rule: the daytime from sunrise to sunset is split into 8 equal
 * parts. Each weekday has a fixed part for each period. These are calculated,
 * never generated by AI, so the times are reliable and testable.
 */

export interface Location {
  name: string;
  latitude: number;
  longitude: number;
  timeZone: string;
}

export interface TimeRange {
  start: string;
  end: string;
}

export interface DayTimings {
  location: string;
  date: string;
  weekday: string;
  sunrise: string;
  sunset: string;
  rahuKalam: TimeRange;
  yamagandam: TimeRange;
  gulikaKalam: TimeRange;
  /** Daytime windows that avoid all three periods. */
  betterWindows: TimeRange[];
}

/** Index 0 = Sunday. Value = which of the 8 daytime parts (1-8). */
const RAHU_PART = [8, 2, 7, 5, 6, 4, 3];
const YAMAGANDAM_PART = [5, 4, 3, 2, 1, 7, 6];
const GULIKA_PART = [7, 6, 5, 4, 3, 2, 1];
const WEEKDAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

const RAD = Math.PI / 180;
const ZENITH = 90.833; // official sunrise/sunset, includes refraction

function dayOfYear(y: number, m: number, d: number): number {
  return Math.round((Date.UTC(y, m - 1, d) - Date.UTC(y, 0, 0)) / 86_400_000);
}

function normalize(value: number, max: number): number {
  return ((value % max) + max) % max;
}

/**
 * Sunrise or sunset as a UTC Date, using the standard NOAA / Almanac for
 * Computers algorithm (accurate to about a minute).
 */
export function sunEvent(
  isoDate: string,
  latitude: number,
  longitude: number,
  kind: "sunrise" | "sunset",
): Date | null {
  const [y, m, d] = isoDate.split("-").map(Number);
  const n = dayOfYear(y, m, d);
  const lngHour = longitude / 15;
  const t = n + ((kind === "sunrise" ? 6 : 18) - lngHour) / 24;
  const meanAnomaly = 0.9856 * t - 3.289;
  const trueLong = normalize(
    meanAnomaly + 1.916 * Math.sin(meanAnomaly * RAD) + 0.02 * Math.sin(2 * meanAnomaly * RAD) + 282.634,
    360,
  );
  let ra = normalize(Math.atan(0.91764 * Math.tan(trueLong * RAD)) / RAD, 360);
  ra += Math.floor(trueLong / 90) * 90 - Math.floor(ra / 90) * 90;
  ra /= 15;
  const sinDec = 0.39782 * Math.sin(trueLong * RAD);
  const cosDec = Math.cos(Math.asin(sinDec));
  const cosH = (Math.cos(ZENITH * RAD) - sinDec * Math.sin(latitude * RAD)) / (cosDec * Math.cos(latitude * RAD));
  if (cosH > 1 || cosH < -1) return null; // polar day or night
  const hourAngle = (kind === "sunrise" ? 360 - Math.acos(cosH) / RAD : Math.acos(cosH) / RAD) / 15;
  const localMean = normalize(hourAngle + ra - 0.06571 * t - 6.622, 24);
  const utHours = localMean - lngHour; // may fall on the previous or next UTC day
  return new Date(Date.UTC(y, m - 1, d) + utHours * 3_600_000);
}

function formatTime(date: Date, timeZone: string): string {
  return new Intl.DateTimeFormat("en-IN", {
    timeZone,
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  })
    .format(date)
    .toUpperCase();
}

function part(sunrise: Date, segmentMs: number, index: number): { start: Date; end: Date } {
  const start = new Date(sunrise.getTime() + (index - 1) * segmentMs);
  return { start, end: new Date(start.getTime() + segmentMs) };
}

export function weekdayOf(isoDate: string): number {
  const [y, m, d] = isoDate.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay();
}

export function calculateTimings(isoDate: string, location: Location): DayTimings | null {
  const sunrise = sunEvent(isoDate, location.latitude, location.longitude, "sunrise");
  const sunset = sunEvent(isoDate, location.latitude, location.longitude, "sunset");
  if (!sunrise || !sunset || sunset <= sunrise) return null;

  const weekday = weekdayOf(isoDate);
  const segment = (sunset.getTime() - sunrise.getTime()) / 8;
  const fmt = (r: { start: Date; end: Date }): TimeRange => ({
    start: formatTime(r.start, location.timeZone),
    end: formatTime(r.end, location.timeZone),
  });

  const blocked = new Set([RAHU_PART[weekday], YAMAGANDAM_PART[weekday], GULIKA_PART[weekday]]);
  const betterWindows: TimeRange[] = [];
  let runStart: number | null = null;
  for (let i = 1; i <= 9; i++) {
    const free = i <= 8 && !blocked.has(i);
    if (free && runStart === null) runStart = i;
    if (!free && runStart !== null) {
      const start = part(sunrise, segment, runStart).start;
      const end = part(sunrise, segment, i - 1).end;
      betterWindows.push(fmt({ start, end }));
      runStart = null;
    }
  }

  return {
    location: location.name,
    date: isoDate,
    weekday: WEEKDAYS[weekday],
    sunrise: formatTime(sunrise, location.timeZone),
    sunset: formatTime(sunset, location.timeZone),
    rahuKalam: fmt(part(sunrise, segment, RAHU_PART[weekday])),
    yamagandam: fmt(part(sunrise, segment, YAMAGANDAM_PART[weekday])),
    gulikaKalam: fmt(part(sunrise, segment, GULIKA_PART[weekday])),
    betterWindows,
  };
}
